/*
 * SOL 500 — the real NASA photos the surface's ground is painted with. src/surface-paint.js makes each one repeat
 * without a seam and lays it over the ground's own colour; their sources are SOURCES.photo* in src/i18n.js.
 * Generated, not edited by hand: each is a square cut from the photo's full-size original (images-assets.nasa.gov/image/<id>/),
 * scaled to 624 px and saved as a JPEG of quality 85:
 *   flagstone PIA24593  x 2650, y 1550, 850 px  Ingenuity, flight 2 (22 Apr 2021): the floor of Jezero Crater from 5.2 m up
 *   cobbles   PIA25890  x 2300, y 1500, 1200 px Ingenuity, flight 48 (21 Mar 2023): the rocks of "Castell Henllys" from 12 m up
 *   sand      PIA26243  x 1700, y 250, 800 px   Ingenuity after flight 72 (Jan 2024): windblown sand
 *   dust      PIA24650  x 1500, y 1200, 1200 px Ingenuity, flight 5 (7 May 2021): fine dust from 10 m up
 *   grains    PIA20171  x 200, y 0, 1198 px     Curiosity MAHLI (5 Dec 2015): dark grains on "High Dune", 3.6 cm across
 *   phoenix   PIA10713  x 1000, y 1950, 1000 px Phoenix SSI, sol 2 (May 2008): the polygonal terrain near the lander
 */
